
// We pull these directly from the hidden inputs generated by PHP
const baseprice = parseInt(document.getElementById("js-base-price").value);
const maxSeats = parseInt(document.getElementById("js-available-seats").value);

// Increment fxn
function incr(event){
    event.preventDefault();
    const number = parseInt(document.getElementById("number").innerText);
    const number1 = parseInt(document.getElementById("number1").innerText);
    
    if(number >= 5){
        alert("Max ticket limit reached!");
        return;
    }
    if(number >= maxSeats){
        alert("Seat limit exceeded!");
        return;
    }
    
    let newnum = number + 1;
    let new1num = number1 + 1;
    let newp = baseprice * newnum;
    
    document.getElementById("number").innerText = String(newnum) + " ";
    document.getElementById("number1").innerText = String(new1num);
    document.getElementById("price").innerText = String(newp);

    // Update the hidden form inputs for processbook.php
    document.getElementById("hidden_ticket_quantity").value = newnum;
    document.getElementById("hidden_total_amount").value = newp;
}

// Decrement fxn
function decr(event){
    event.preventDefault();
    const number = parseInt(document.getElementById("number").innerText);
    const number1 = parseInt(document.getElementById("number1").innerText);
    
    if(number <= 1){
        return;
    }
    
    let newnum = number - 1;
    let new1num = number1 - 1;
    let newp = baseprice * newnum;
    
    document.getElementById("number").innerText = String(newnum) + " ";
    document.getElementById("number1").innerText = String(new1num);
    document.getElementById("price").innerText = String(newp);

    // Update the hidden form inputs for processbook.php
    document.getElementById("hidden_ticket_quantity").value = newnum;
    document.getElementById("hidden_total_amount").value = newp;
}

// Booking Validation fxn
function Book(event){
    const number = parseInt(document.getElementById("number").innerText);
    
    // Run our seat validation checks before allowing the form to submit
    if (maxSeats === 0) {
        alert("Booking limit full! Event is sold out.");
        event.preventDefault();
        return;
    }
    if (number > maxSeats) {
        alert("Seat limit exceeded!");
        event.preventDefault(); 
        return;
    }

    // and sends the data straight to processbook.php!
}